// TypeScript port of /workspace/calorie-tracker/internal/parser/parser.go.
// Same rules.json + dishes.json; parity is enforced by __tests__/parser.test.ts
// against outputs generated by the Go parser (src/data/golden.json).
// Keep this file a line-by-line mirror of the Go code when either changes.

export type Unit = 'count' | 'katori' | 'spoon' | 'plate' | 'glass' | 'gram' | string;
export type OilLevel = '' | 'less' | 'normal' | 'extra';

export interface Dish {
  id: string; name: string; aliases: string[]; unit: Unit; portion_grams: number;
  kcal: number; kcal_low: number; kcal_high: number;
  protein_g: number; protein_low: number; protein_high: number;
  oil_sensitive: boolean; source: string; source_note: string;
  diet?: 'veg' | 'egg' | 'nonveg'; category?: string; brand?: string; is_estimate?: boolean; version?: number;
}
interface UnitRule { words: string[]; grams: number; as?: string; factor?: number }
export interface Rules {
  numbers: Record<string, number>; half_suffixes: string[]; units: Record<string, UnitRule>;
  oil_words: Record<string, string[]>; oil_nouns: string[]; small_words: string[]; fat_dishes: string[];
  small_fat_spoons: number; default_fat_spoons: number; extra_fat_spoons: number; oil_kcal_per_150g: number;
  fillers: string[]; fuzzy_min_len: number; fuzzy_max_dist: number;
}
export interface Range { low: number; best: number; high: number }
export interface Item {
  dish_id: string; name: string; matched_text: string; quantity: number; unit: Unit; grams: number;
  oil_level: OilLevel; kcal: Range; protein_g: Range; source: string; source_note: string;
  fuzzy: boolean; ai_estimate: boolean;
}
export interface ParseResult { items: Item[]; unmatched: string[] }

interface Token { w: string; num: number; isN: boolean; sep: boolean }
const tok = (p: Partial<Token>): Token => ({ w: '', num: 0, isN: false, sep: false, ...p });
interface Pending { qty: number; hasQty: boolean; unit: string; factor: number; oil: string; small: boolean }
const emptyPending = (): Pending => ({ qty: 0, hasQty: false, unit: '', factor: 0, oil: '', small: false });

/** Go's math.Round (half away from zero) to d decimals. */
export function round(f: number, d: number): number {
  const m = Math.pow(10, d);
  const x = f * m;
  return (x < 0 ? -Math.round(-x) : Math.round(x)) / m;
}
// Go's strconv.FormatFloat(f,'f',-1,64) == shortest repr; JS String() matches for normal ranges.
const fmt = (n: number) => String(n);
const goParseFloat = (f: string) => {
  const m = /^([+-]?)(inf|infinity)$/i.exec(f);
  if (m) return m[1] === '-' ? -Infinity : Infinity;
  return /^[+-]?nan$/i.test(f) ? NaN : parseFloat(f);
};
const fields = (s: string) => s.split(/\s+/).filter(Boolean);

export class Parser {
  private dish = new Map<string, Dish>();
  private byId = new Map<string, Dish>();
  private maxLen = 0;
  private single: string[] = [];
  private unitOf = new Map<string, string>();
  private oilOf = new Map<string, string>();
  private small: Set<string>; private oilNoun: Set<string>; private filler: Set<string>; private fat: Set<string>;

  constructor(dishes: Dish[], private r: Rules) {
    for (const d of dishes) {
      if (!this.byId.has(d.id)) this.byId.set(d.id, d);
      for (let t of [d.name, d.id, ...(d.aliases ?? [])]) {
        t = fields(t.replaceAll('_', ' ').toLowerCase()).join(' ');
        if (this.dish.has(t)) continue;
        this.dish.set(t, d);
        const n = fields(t).length;
        if (n > this.maxLen) this.maxLen = n;
        if (n === 1 && t.length >= r.fuzzy_min_len) this.single.push(t);
      }
    }
    for (const [u, ur] of Object.entries(r.units)) for (const w of ur.words) this.unitOf.set(w, u);
    for (const [lvl, ws] of Object.entries(r.oil_words)) for (const w of ws) this.oilOf.set(w, lvl);
    this.small = new Set(r.small_words); this.oilNoun = new Set(r.oil_nouns);
    this.filler = new Set(r.fillers); this.fat = new Set(r.fat_dishes);
  }

  dishById(id: string): Dish | undefined { return this.byId.get(id); }
  allDishes(): Dish[] { return [...this.byId.values()]; }

  private normalize(s: string): string {
    s = s.toLowerCase();
    s = s.replace(/(\d+)\s*\/\s*(\d+)/g, (m, a, b) => (Number(b) === 0 ? m : fmt(Number(a) / Number(b))));
    s = s.replaceAll('½', ' 0.5 ');
    s = s.replace(/[^a-z0-9.½&+ ]+/g, ' , ');
    s = s.replaceAll('&', ' & ').replaceAll('+', ' + ');
    s = s.replace(/(\d+(?:\.\d+)?)([a-z]+)/g, '$1 $2');
    s = ' ' + fields(s).join(' ') + ' ';
    for (const suf of this.r.half_suffixes) s = s.replaceAll(' ' + suf + ' ', ' +0.5 ');
    return s;
  }

  private tokenize(s: string): Token[] {
    const out: Token[] = [];
    for (let f of fields(this.normalize(s))) {
      if (f === ',' || f === '.') { out.push(tok({ sep: true })); continue; }
      f = f.replace(/^\.+|\.+$/g, '');
      if (f === '') continue;
      if (f === '+0.5') {
        const n = out.length;
        if (n > 0 && out[n - 1].isN) out[n - 1].num += 0.5;
        else out.push(tok({ num: 1.5, isN: true }));
        continue;
      }
      if (/^[+-]?(inf|infinity|nan)$/i.test(f) || /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(f)) { out.push(tok({ num: goParseFloat(f), isN: true })); continue; }
      if (f in this.r.numbers) { out.push(tok({ w: f, num: this.r.numbers[f], isN: true })); continue; }
      out.push(tok({ w: f }));
    }
    return out;
  }

  private word(t: Token) { return t.w !== '' ? t.w : fmt(t.num); }

  private matchDish(toks: Token[], i: number): [Dish | null, number, boolean] {
    for (let n = this.maxLen; n >= 1; n--) {
      if (i + n > toks.length) continue;
      const ws: string[] = []; let ok = true;
      for (const t of toks.slice(i, i + n)) { if (t.sep || t.w === '') { ok = false; break; } ws.push(t.w); }
      if (!ok) continue;
      const term = ws.join(' ');
      const d = this.dish.get(term);
      if (d) return [d, n, false];
      if (n === 1) {
        const trim = (s: string, suf: string) => (s.endsWith(suf) ? s.slice(0, -suf.length) : s);
        for (const alt of [trim(term, 's'), trim(term, 'es'), trim(term, 'an')]) {
          const a = this.dish.get(alt);
          if (a && alt !== term) return [a, 1, false];
        }
        if (term.length >= this.r.fuzzy_min_len) {
          let best = '', bd = this.r.fuzzy_max_dist + 1;
          for (const c of this.single) { const dd = lev(term, c, bd); if (dd < bd) { best = c; bd = dd; } }
          if (best !== '') return [this.dish.get(best)!, 1, true];
        }
      }
    }
    return [null, 0, false];
  }

  parse(text: string): ParseResult {
    const toks = this.tokenize(text);
    const res: ParseResult = { items: [], unmatched: [] };
    let pd = emptyPending();
    let unk: string[] = [];
    let lastExplicit = false;
    const flushUnk = () => { if (unk.length > 0) { res.unmatched.push(unk.join(' ')); unk = []; } };
    const lastIdx = () => res.items.length - 1;
    for (let i = 0; i < toks.length; i++) {
      const t = toks[i];
      if (t.sep) { flushUnk(); continue; }
      if (!t.isN || t.w === '') {
        const [d, n, fz] = this.matchDish(toks, i);
        if (d) {
          flushUnk();
          const matched = toks.slice(i, i + n).map((x) => this.word(x)).join(' ');
          res.items.push(this.build(d, pd, matched, fz));
          lastExplicit = pd.hasQty || pd.unit !== '';
          pd = emptyPending();
          i += n - 1;
          continue;
        }
      }
      if (t.isN) {
        const li = lastIdx();
        if (li >= 0 && !lastExplicit && !pd.hasQty && this.trailing(toks, i)) {
          let u = '', f = 1;
          if (i + 1 < toks.length && !toks[i + 1].sep) {
            [u, f] = this.unitFor(toks[i + 1].w);
            if (u !== '') i++;
          }
          res.items[li] = this.rescale(res.items[li], t.num * f, u);
          lastExplicit = true;
          continue;
        }
        if (t.w !== '' && (i + 1 >= toks.length || toks[i + 1].sep)) continue;
        if (pd.hasQty) pd.qty *= t.num; else { pd.qty = t.num; pd.hasQty = true; }
        continue;
      }
      const w = t.w;
      const [u, f] = this.unitFor(w);
      if (u !== '') {
        if (!pd.hasQty) { pd.qty = 1; pd.hasQty = true; }
        pd.unit = u; pd.factor = f;
        continue;
      }
      if (this.small.has(w)) { pd.small = true; continue; }
      const lvl = this.oilOf.get(w);
      if (lvl !== undefined) {
        const li = lastIdx();
        if (li >= 0 && i + 1 < toks.length && this.oilNoun.has(toks[i + 1].w) && res.items[li].oil_level !== '') {
          res.items[li] = this.withOil(res.items[li], lvl as OilLevel);
          i++;
          continue;
        }
        pd.oil = lvl;
        continue;
      }
      if (this.filler.has(w)) continue;
      if (pd.hasQty && unk.length === 0) unk.push(fmt(pd.qty));
      pd = emptyPending();
      if (unk.length === 0 && !lastExplicit) {
        const glued: string[] = [];
        for (let k = i - 1; k >= 0; k--) {
          const li = res.items[res.items.length - 1];
          if (!li || toks[k].sep || li.matched_text !== this.word(toks[k]) || li.quantity !== 1) break;
          glued.unshift(li.matched_text);
          res.items.pop();
          if (!li.fuzzy) break;
        }
        unk.push(...glued);
      }
      unk.push(w);
    }
    flushUnk();
    return res;
  }

  private unitFor(w: string): [string, number] {
    const u = this.unitOf.get(w);
    if (u === undefined) return ['', 0];
    const ur = this.r.units[u];
    if (ur.as) return [ur.as, ur.factor ?? 0];
    return [u, 1];
  }

  private trailing(toks: Token[], i: number): boolean {
    let j = i + 1;
    if (j < toks.length && !toks[j].sep) { if (this.unitFor(toks[j].w)[0] !== '') j++; }
    if (j >= toks.length || toks[j].sep) return true;
    if (toks[j].isN) return false;
    return this.filler.has(toks[j].w) && (j + 1 >= toks.length || toks[j + 1].sep);
  }

  private unitGrams(d: Dish, unit: string): number {
    if (unit === '' || unit === d.unit) return d.portion_grams;
    if (unit === 'count') return d.portion_grams;
    return this.r.units[unit]?.grams ?? 0;
  }

  private build(d: Dish, pd: Pending, matched: string, fuzzy: boolean): Item {
    let qty = 1;
    if (pd.hasQty) qty = pd.qty * (pd.factor === 0 ? 1 : pd.factor);
    const unit = pd.unit;
    if (pd.small && !pd.hasQty && !this.fat.has(d.id)) qty = 0.5;
    if (this.fat.has(d.id) && !pd.hasQty) {
      qty = this.r.default_fat_spoons;
      if (pd.small || pd.oil === 'less') qty = this.r.small_fat_spoons;
      if (pd.oil === 'extra') qty = this.r.extra_fat_spoons;
    }
    let it: Item = {
      dish_id: d.id, name: d.name, matched_text: matched, quantity: 0, unit: '', grams: 0, oil_level: '',
      kcal: { low: 0, best: 0, high: 0 }, protein_g: { low: 0, best: 0, high: 0 },
      source: d.source, source_note: d.source_note, fuzzy, ai_estimate: false,
    };
    it = this.compute(d, it, qty, unit);
    if (d.oil_sensitive) it = this.withOil(it, (pd.oil || 'normal') as OilLevel);
    return it;
  }

  private compute(d: Dish, it: Item, qty: number, unit: string): Item {
    if (unit === '') unit = d.unit;
    let grams = qty * this.unitGrams(d, unit);
    if (unit === 'gram') grams = qty;
    const scale = grams / d.portion_grams;
    return {
      ...it, quantity: round(qty, 2), unit, grams: round(grams, 0),
      kcal: { low: round(d.kcal_low * scale, 0), best: round(d.kcal * scale, 0), high: round(d.kcal_high * scale, 0) },
      protein_g: { low: round(d.protein_low * scale, 1), best: round(d.protein_g * scale, 1), high: round(d.protein_high * scale, 1) },
    };
  }

  rescale(it: Item, qty: number, unit: string): Item {
    const d = this.dishById(it.dish_id)!;
    const lvl = it.oil_level;
    let n = this.compute(d, it, qty, unit);
    n.oil_level = '';
    if (lvl !== '') n = this.withOil(n, lvl);
    return n;
  }

  withOil(it: Item, lvl: OilLevel): Item {
    const d = this.dishById(it.dish_id)!;
    const n = this.compute(d, it, it.quantity, it.unit);
    n.oil_level = lvl;
    const delta = (this.r.oil_kcal_per_150g * n.grams) / 150;
    const k = n.kcal;
    if (lvl === 'less') n.kcal = { low: Math.max(0, round(k.low - delta, 0)), best: Math.max(0, round(k.best - delta, 0)), high: k.high - round(delta / 2, 0) };
    else if (lvl === 'extra') n.kcal = { low: k.low + round(delta / 2, 0), best: round(k.best + delta, 0), high: round(k.high + delta * 1.5, 0) };
    return n;
  }

  /** App-side edit helper: change dish/qty/unit/oil and recompute from the table. */
  edit(it: Item, ch: { dishId?: string; quantity?: number; unit?: string; oil?: OilLevel }): Item {
    const d = this.dishById(ch.dishId ?? it.dish_id)!;
    let n: Item = { ...it, dish_id: d.id, name: d.name, source: d.source, source_note: d.source_note, oil_level: '' };
    n = this.compute(d, n, ch.quantity ?? it.quantity, ch.unit ?? (ch.dishId ? d.unit : it.unit));
    if (d.oil_sensitive) n = this.withOil(n, ch.oil || it.oil_level || 'normal');
    return n;
  }
}

export function lev(a: string, b: string, max: number): number {
  const d = a.length - b.length;
  if (d > max || -d > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = new Array<number>(b.length + 1);
    cur[0] = i; let lo = cur[0];
    for (let j = 1; j <= b.length; j++) {
      const c = a[i - 1] === b[j - 1] ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + c);
      lo = Math.min(lo, cur[j]);
    }
    if (lo > max) return max + 1;
    prev = cur;
  }
  return prev[b.length];
}

export function totals(items: Pick<Item, 'kcal' | 'protein_g'>[]): [Range, Range] {
  const k = { low: 0, best: 0, high: 0 }, p = { low: 0, best: 0, high: 0 };
  for (const it of items) {
    k.low += it.kcal.low; k.best += it.kcal.best; k.high += it.kcal.high;
    p.low += it.protein_g.low; p.best += it.protein_g.best; p.high += it.protein_g.high;
  }
  return [k, { low: round(p.low, 1), best: round(p.best, 1), high: round(p.high, 1) }];
}
